g2=[[1]*19 for _ in range(13)]
# Full connected source motif, including the two cells above the 3x3 body.
seed2={(4,11):4,(5,11):5,(6,10):9,(6,11):9,(6,12):3,(7,10):7,(7,11):5,(7,12):5,(8,11):7}
for (r,c),v in seed2.items(): g2[r][c]=v
marks=[(2,1),(3,17),(5,5),(9,3),(9,16)]
# Bounding box is 5x3; central anchor is (r+2,c+1), color 9.
shape={(-2,0):4,(-1,0):5,(0,-1):9,(0,0):9,(0,1):3,(1,-1):7,(1,0):5,(1,1):5,(2,0):7}
for r,c in marks:
    for (dr,dc),v in shape.items():
        rr,cc=r+dr,c+dc
        assert 0<=rr<13 and 0<=cc<19
        g2[rr][cc]=v
print('\n'.join(' '.join(map(str,row)) for row in g2))
